// Toggle mount mode
StelMovementMgr.toggleMountMode();

// Read the resulting mode
var isEq = StelMovementMgr.getEquatorialMount();
core.debug("Equatorial mount: " + isEq);

// Switch to equatorial mount
StelMovementMgr.setEquatorialMount(true);

// Switch to alt-azimuthal mount
StelMovementMgr.setEquatorialMount(false);

// Read current state
var isEq = StelMovementMgr.getEquatorialMount();
core.debug("Equatorial mount: " + isEq);

// Enable tracking of the selected object
StelMovementMgr.setFlagTracking(true);

// Disable tracking
StelMovementMgr.setFlagTracking(false);

// Read current state
var isTracking = StelMovementMgr.getFlagTracking();
core.debug("Tracking: " + isTracking);

var isTracking = StelMovementMgr.getFlagTracking();
core.debug("Tracking: " + isTracking);

// Alternative via Q_PROPERTY
var isTracking2 = core.getStelProperty('StelMovementMgr.tracking');
core.debug("Tracking (property): " + isTracking2);

StelMovementMgr.setFlagLockEquPos(true);
StelMovementMgr.setFlagLockEquPos(false);

var locked = StelMovementMgr.getFlagLockEquPos();
core.debug("Equatorial locked: " + locked);

// Faster auto-moves
StelMovementMgr.setAutoMoveDuration(0.8);

// Slower, more cinematic moves
StelMovementMgr.setAutoMoveDuration(3.0);

var dur = StelMovementMgr.getAutoMoveDuration();
core.debug("Auto-move duration: " + dur);

// Enable direction reset on auto-zoom out
StelMovementMgr.setFlagAutoZoomOutResetsDirection(true);

// Disable it (preserve current direction)
StelMovementMgr.setFlagAutoZoomOutResetsDirection(false);

// Read current state
var reset = StelMovementMgr.getFlagAutoZoomOutResetsDirection();
core.debug("Auto-zoom out resets direction: " + reset);

StelMovementMgr.setFlagEnableZoomKeys(true);
StelMovementMgr.setFlagEnableZoomKeys(false);

var enabled = StelMovementMgr.getFlagEnableZoomKeys();

StelMovementMgr.setFlagEnableMoveKeys(true);
StelMovementMgr.setFlagEnableMoveKeys(false);

var enabled = StelMovementMgr.getFlagEnableMoveKeys();

StelMovementMgr.setFlagEnableMoveAtScreenEdge(true);
StelMovementMgr.setFlagEnableMoveAtScreenEdge(false);

var enabled = StelMovementMgr.getFlagEnableMoveAtScreenEdge();

StelMovementMgr.setFlagEnableMouseNavigation(true);
StelMovementMgr.setFlagEnableMouseNavigation(false);

var enabled = StelMovementMgr.getFlagEnableMouseNavigation();

StelMovementMgr.setFlagEnableMouseZooming(true);
StelMovementMgr.setFlagEnableMouseZooming(false);

var enabled = StelMovementMgr.getFlagEnableMouseZooming();

StelMovementMgr.setFlagIndicationMountMode(true);
StelMovementMgr.setFlagIndicationMountMode(false);

var shown = StelMovementMgr.getFlagIndicationMountMode();

// Move to RA 0h, Dec 0°, over 2 seconds
var aim = new V3d('0h', '0d').toVec3d();
var up = new V3d(0, 0, 1).toVec3d();
StelMovementMgr.moveToJ2000(aim, up, 2.0, 0);

// Zoom in while moving
StelMovementMgr.moveToJ2000(aim, up, 1.5, 1);

// Switch to Alt-Azimuth mode first
StelMovementMgr.setEquatorialMount(false);

// Move to the zenith
var aim = new V3d(0, 0, 1).toVec3d();
var up = new V3d(0, 0, 1).toVec3d();
StelMovementMgr.moveToAltAzi(aim, up, 1.5, 0);

// Smooth zoom to 5 degrees over 2 seconds
StelMovementMgr.zoomTo(5.0, 2.0);

// Instant zoom
StelMovementMgr.zoomTo(60.0, 0);

var fov = StelMovementMgr.getCurrentFov();
core.debug("Current FOV: " + fov + '°');

// Alternative via Q_PROPERTY
var fov2 = core.getStelProperty('StelMovementMgr.currentFov');

StelMovementMgr.setInitFov(45.0);

var fov = StelMovementMgr.getInitFov();
core.debug("Initial FOV: " + fov + '°');

var dir = new V3d(StelMovementMgr.getInitViewingDirection());
core.debug("Init direction: " + dir.toVec3d());
core.debug("x=" + dir.x() + ' y=' + dir.y() + ' z=' + dir.z());

var dir = new V3d(StelMovementMgr.getViewDirectionJ2000());
core.debug("Direction: " + dir.toVec3d());
core.debug("x=" + dir.x() + ' y=' + dir.y() + ' z=' + dir.z());

// Set view direction to RA 0h, Dec 0°
var dir = new V3d('0h', '0d').toVec3d();
StelMovementMgr.setViewDirectionJ2000(dir);

// Read back
var current = new V3d(StelMovementMgr.getViewDirectionJ2000());
core.debug("New direction: " + current.toVec3d());

StelMovementMgr.setMaxFov(180.0);

var maxFov = StelMovementMgr.getMaxFov();
core.debug("Max FOV: " + maxFov + '°');

StelMovementMgr.turnRight(true);
core.wait(1);
StelMovementMgr.turnRight(false);

StelMovementMgr.turnLeft(true);
core.wait(1);
StelMovementMgr.turnLeft(false);

StelMovementMgr.turnUp(true);
core.wait(1);
StelMovementMgr.turnUp(false);

StelMovementMgr.turnDown(true);
core.wait(1);
StelMovementMgr.turnDown(false);

StelMovementMgr.moveSlow(true);
core.wait(2);
StelMovementMgr.moveSlow(false);

StelMovementMgr.zoomIn(true);
core.wait(2);
StelMovementMgr.zoomIn(false);

StelMovementMgr.zoomOut(true);
core.wait(2);
StelMovementMgr.zoomOut(false);

// Smoothly pan 30 degrees to the right
StelMovementMgr.smoothPan(30, 0, 2.0, true);
core.wait(2);
StelMovementMgr.smoothPan(30, 0, 2.0, false);

StelMovementMgr.setMountMode(0);
StelMovementMgr.setMountMode(1);

var mode = StelMovementMgr.getMountMode();
core.debug("Mount mode: " + mode);

var isEq = StelMovementMgr.getEquatorialMount();
core.debug("Equatorial mount: " + isEq);

// Alternative via Q_PROPERTY
var isEq2 = core.getStelProperty('StelMovementMgr.equatorialMount');

var target = StelMovementMgr.getViewportOffsetTarget();
core.debug("Viewport target: " + target);

// Or use the individual components
var x = StelMovementMgr.getViewportHorizontalOffsetTarget();
var y = StelMovementMgr.getViewportVerticalOffsetTarget();
core.debug('X=' + x + ' Y=' + y);

StelMovementMgr.setViewportHorizontalOffsetTarget(10);

var x = StelMovementMgr.getViewportHorizontalOffsetTarget();
core.debug('X target: ' + x + '%');

StelMovementMgr.setViewportVerticalOffsetTarget(-15);

var y = StelMovementMgr.getViewportVerticalOffsetTarget();
core.debug('Y target: ' + y + '%');

StelMovementMgr.setUserMaxFov(180.0);
StelMovementMgr.setUserMaxFov(360.0);

var maxFov = StelMovementMgr.getUserMaxFov();
core.debug('User max FOV: ' + maxFov + '°');

StelMovementMgr.setFov(10.0);
StelMovementMgr.setFov(90.0);

var current = StelMovementMgr.getCurrentFov();
core.debug('Current FOV: ' + current + '°');
